import 'dart:convert';

/// One range of verses: book id, from chapter:verse to chapter:verse.
class VerseRange {
  const VerseRange(this.book, this.c1, this.v1, this.c2, this.v2);

  factory VerseRange.fromJson(List<Object?> j) => VerseRange(
        j[0]! as String,
        (j[1]! as num).toInt(),
        (j[2]! as num).toInt(),
        (j[3]! as num).toInt(),
        (j[4]! as num).toInt(),
      );

  final String book;
  final int c1;
  final int v1;
  final int c2;
  final int v2;
}

/// The Liturgy readings of one day, from assets/data/lecturi.json.
///
/// The file is generated by tool/lectionary.py (troita repo) and copied to
/// troita.ro, so the app and the site read the same pericope on the same day.
class LecturaZi {
  const LecturaZi({
    this.apostol = const <VerseRange>[],
    this.apostolCite,
    this.evanghelie = const <VerseRange>[],
    this.evanghelieCite,
    this.title,
    this.none,
  });

  factory LecturaZi.fromJson(Map<String, Object?> j) {
    List<VerseRange> ranges(Object? v) => v == null
        ? const <VerseRange>[]
        : (v as List<Object?>)
            .map((Object? r) => VerseRange.fromJson(r! as List<Object?>))
            .toList(growable: false);
    return LecturaZi(
      apostol: ranges(j['ap']),
      apostolCite: j['apCite'] as String?,
      evanghelie: ranges(j['ev']),
      evanghelieCite: j['evCite'] as String?,
      title: j['title'] as String?,
      none: j['none'] as String?,
    );
  }

  final List<VerseRange> apostol;

  /// "Romani 2, 10-16".
  final String? apostolCite;
  final List<VerseRange> evanghelie;

  /// "Matei 4, 18-23".
  final String? evanghelieCite;

  /// "Duminica a II-a după Rusalii", on Sundays that have a number.
  final String? title;

  /// Why there is no reading: "Postul Mare: zi fără Liturghie".
  final String? none;

  bool get hasGospel => none == null && evanghelie.isNotEmpty;
}

class Lecturi {
  Lecturi(this._days);

  factory Lecturi.parse(String json) {
    final Map<String, Object?> doc = jsonDecode(json) as Map<String, Object?>;
    final Map<String, Object?> days = doc['days']! as Map<String, Object?>;
    return Lecturi(<String, LecturaZi>{
      for (final MapEntry<String, Object?> e in days.entries)
        e.key: LecturaZi.fromJson(e.value! as Map<String, Object?>),
    });
  }

  final Map<String, LecturaZi> _days;

  /// The readings of [date], or null outside the generated years.
  LecturaZi? on(DateTime date) => _days[_iso(date)];

  static String _iso(DateTime d) =>
      '${d.year}-${d.month.toString().padLeft(2, '0')}-'
      '${d.day.toString().padLeft(2, '0')}';
}

/// One verse of the text, with its place.
class Verse {
  const Verse(this.chapter, this.number, this.text);

  final int chapter;
  final int number;
  final String text;
}

/// The New Testament, from assets/data/biblia_nt.json: the 1988 Synodal
/// edition of the Romanian Orthodox Church (IBMBOR).
class BibliaNT {
  BibliaNT(this._books, this.source);

  factory BibliaNT.parse(String json) {
    final Map<String, Object?> doc = jsonDecode(json) as Map<String, Object?>;
    final Map<String, List<List<String>>> books = <String, List<List<String>>>{};
    for (final Object? b in doc['books']! as List<Object?>) {
      final Map<String, Object?> book = b! as Map<String, Object?>;
      books[book['id']! as String] = <List<String>>[
        for (final Object? c in book['chapters']! as List<Object?>)
          (c! as List<Object?>).cast<String>(),
      ];
    }
    return BibliaNT(books, doc['source']! as String);
  }

  final Map<String, List<List<String>>> _books;

  /// "Biblia, ediția Sfântului Sinod, IBMBOR, 1988" — shown under the text.
  final String source;

  /// The verses of a pericope, in reading order.
  List<Verse> text(List<VerseRange> pericope) {
    final List<Verse> out = <Verse>[];
    for (final VerseRange r in pericope) {
      final List<List<String>>? book = _books[r.book];
      if (book == null) continue;
      for (int c = r.c1; c <= r.c2 && c <= book.length; c++) {
        final List<String> chapter = book[c - 1];
        final int from = c == r.c1 ? r.v1 : 1;
        final int to = c == r.c2 ? r.v2 : chapter.length;
        for (int v = from; v <= to && v <= chapter.length; v++) {
          out.add(Verse(c, v, chapter[v - 1]));
        }
      }
    }
    return out;
  }
}

/// The sub-tabs of Lecturi. Rugăciuni will come third; it has no date.
enum ReadingTab { sinaxar, evanghelie }
